/* Original usable commands: preflight all output items before consuming input. */
#include "item_use_data52.h"
typedef struct{unsigned command,count;int args[5];}ItemUseAction52;
typedef struct{ItemUseAction52 actions[32];unsigned count;int failed;}ItemUsePlan52;
static ItemUsePlan52*itemUsePlan52;
static void item_use_plan52(Combat*g,unsigned command,const int*args,unsigned count){(void)g;ItemUsePlan52*p=itemUsePlan52;if(!p)return;if(p->count>=32||count>5){p->failed=1;return;}ItemUseAction52*a=p->actions+p->count++;a->command=command;a->count=count;memcpy(a->args,args,count*sizeof(int));}
static int item_use_group52(Combat*g,unsigned source){for(unsigned i=0;i<sizeof(itemUseGroups52)/sizeof(*itemUseGroups52);i++)if(itemUseGroups52[i].source==source){unsigned roll=combat_random(g)%itemUseGroups52[i].total;for(unsigned n=0;n<itemUseGroups52[i].count;n++){const uint32_t*r=itemUseGroupRows52[itemUseGroups52[i].start+n];if(roll<r[1])return r[0];}}return 0;}
static void item_use_status52(Combat*g,unsigned source,int status,int duration,int value,int chance){if(chance<10000&&!item_chance52(g,chance,10000))return;if(status<11){item_status52(g,NULL,status,duration*.001f);return;}for(unsigned i=0;i<sizeof(itemUseStatus52)/sizeof(*itemUseStatus52);i++)if(itemUseStatus52[i].status==status){unsigned slot=0;int bonus=itemUseStatus52[i].bonus;if(itemUseStatus52[i].fixed)value=itemUseStatus52[i].fixed;for(unsigned n=0;n<16;n++){ItemUseBuff52*b=g->class50.itemUseBuffs52+n;if(b->status==status){slot=n;break;}if(b->until<=g->time){slot=n;break;}if(b->until<g->class50.itemUseBuffs52[slot].until)slot=n;}/* Attack-speed potions share a source family; the strongest wins. */if(status>=55&&status<=57)for(unsigned n=0;n<16;n++){ItemUseBuff52*b=g->class50.itemUseBuffs52+n;if(b->until>g->time&&b->status>=55&&b->status<=57){if(b->value>value)return;b->until=0;}}g->class50.itemUseBuffs52[slot]=(ItemUseBuff52){status,bonus,value,source,g->time+duration*.001f};return;}}
static void item_use_cure52(Combat*g,int status){switch(status){case 0:case 1:case 2:case 3:g->hitStun=0;break;case 4:g->poisonLeft=g->poisonTick=0;break;case 6:g->silenceLeft=0;break;case 8:g->blindLeft=0;break;case 7:g->confusionLeft=0;break;default:break;}}
static void item_use_heal52(Combat*g,int source,int hp,int sp){if(hp>0){hp=item_clamp52((int64_t)hp*(100+2*stat_value(g,2))/100);hp=item_clamp52((int64_t)hp*(100+10*skill_rank(g,26)+5*class_rank50(g,238)+item_bonus_match52(g,B52_bAddItemHealRate,source,-1))/100);}if(sp>0){sp=item_clamp52((int64_t)sp*(100+2*stat_value(g,3))/100);sp=item_clamp52((int64_t)sp*(100+10*skill_rank(g,25)+5*class_rank50(g,238))/100);}item_heal52(g,hp,sp);}
static int item_use52(Combat*g,unsigned source){if(combat_merc_item180){int handled=combat_merc_item180(combat_npc_context55,g,source);if(handled>=0)return handled;}unsigned lo=0,hi=sizeof(itemUses52)/sizeof(*itemUses52);while(lo<hi){unsigned mid=(lo+hi)/2;if(itemUses52[mid].source<source)lo=mid+1;else hi=mid;}if(lo>=sizeof(itemUses52)/sizeof(*itemUses52)||itemUses52[lo].source!=source){unsigned a=0,b=sizeof(itemUseDeferred52)/sizeof(*itemUseDeferred52);while(a<b){unsigned mid=(a+b)/2;if(itemUseDeferred52[mid]<source)a=mid+1;else b=mid;}if(a<sizeof(itemUseDeferred52)/sizeof(*itemUseDeferred52)&&itemUseDeferred52[a]==source){combat_notice(g,POP_ITEMS,"This item needs a later system. Item kept.");return 1;}return 0;}const ItemScript52*script=itemUses52+lo;ItemUsePlan52 plan={0};itemUsePlan52=&plan;int valid=item_script_run52(g,NULL,itemUseWords52+script->start,script->count);itemUsePlan52=NULL;if(!valid||plan.failed||!plan.count)return 1;
 /* Static staging keeps the large owned bank off the Xbox stack. */
 static OwnedItems52 candidate;candidate=g->owned52;inventory_compact52(&candidate);uint32_t uid=0;for(unsigned i=0;i<candidate.count[0];i++)if(candidate.items[i].sourceID==source&&candidate.items[i].quantity){uid=candidate.items[i].uid;break;}if(!uid||owned_remove52(&candidate,0,uid,1)!=OWNED_OK52)return 1;int useful=0,queued=0;for(unsigned n=0;n<8;n++)queued+=g->class50.itemSpells52[n].skill!=0;
 for(unsigned i=0;i<plan.count;i++){ItemUseAction52*a=plan.actions+i;int*v=a->args;if(a->command==6){if(a->count<2||v[1]!=1){plan.failed=1;break;}int output=item_use_group52(g,v[0]);if(!output){plan.failed=1;break;}a->command=5;v[0]=output;v[1]=1;}
  if(a->command==5){if(a->count<2||v[1]<=0||owned_add52(&candidate,0,(uint32_t)v[0],(uint32_t)v[1],item_rule52)!=OWNED_OK52){plan.failed=1;break;}useful=1;}
  else if(a->command==4){int id=item_script_native52(v[0]);if(++queued>8||id<=0||id>=SKILL_COUNT||v[1]<=0||v[1]>10||(skill_cast_targeted(id)&&(g->target<0||g->target>=MOB_COUNT||g->mobs[g->target].hp<=0))){plan.failed=1;break;}useful=1;}
  else if(a->command==0||a->command==1||a->command==7){if((v[0]>0&&g->hp<g->maxhp)||(v[1]>0&&g->sp<g->maxsp)||v[0]<0||v[1]<0)useful=1;}
  else useful=1;
 }
 int64_t weight=0;for(unsigned i=0;i<candidate.count[0];i++){const OwnedRule52*r=item_rule52(candidate.items[i].sourceID);if(r)weight+=(int64_t)r->weight*candidate.items[i].quantity;}if(plan.failed||weight>inventory_weight_max(g)){combat_notice(g,POP_ITEMS,"Not enough bag space or weight capacity. Item kept.");return 1;}if(!useful){combat_notice(g,POP_ITEMS,"HP/SP already full. Item kept.");return 1;}
 g->owned52=candidate;
 for(unsigned i=0;i<plan.count&&g->hp>0;i++){ItemUseAction52*a=plan.actions+i;int*v=a->args;if(a->command==0)item_use_heal52(g,source,v[0],v[1]);else if(a->command==1)item_heal52(g,(int)((int64_t)g->maxhp*v[0]/100),(int)((int64_t)g->maxsp*v[1]/100));else if(a->command==2){item_use_status52(g,source,v[0],v[1],v[2],a->count>=4?v[3]:10000);stat_refresh(g);}else if(a->command==3)item_use_cure52(g,v[0]);else if(a->command==4)item_queue_spell52(g,v[0],v[1],g->target,0,0);else if(a->command==7)item_heal52(g,v[0],v[1]);}
 stat_refresh(g);combat_notice(g,POP_ITEMS,"Used %s.",itemDefs[inventory_catalog52(source)].name);return 1;
}
